package at.janic.thedarkdimensions.test;

import at.janic.thedarkdimensions.*;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.server.level.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.effect.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.decoration.ArmorStand;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;

final class MasteryTests {
    private static net.minecraft.world.entity.monster.zombie.Zombie enemy(GameTestHelper h,double x,double z){var e=h.spawn(EntityTypes.ZOMBIE,new Vec3(x,2,z));e.setNoAi(true);e.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.IRON_HELMET));e.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);e.setHealth(100);return e;}
    private static void clear(ServerPlayer p){for(var element:MagicElement.values())p.getCooldowns().removeCooldown(p.getCooldowns().getCooldownGroup(new ItemStack(MagicContent.book(element))));p.getCooldowns().removeCooldown(p.getCooldowns().getCooldownGroup(new ItemStack(MagicContent.MASTER_BOOK.get())));}
    private static void select(ServerPlayer p,MagicSkill skill,int choice){var book=new ItemStack(MagicContent.MASTER_BOOK.get());var d=new MagicData();d.elements=255;d.learned=1L<<skill.ordinal();d.uses[skill.ordinal()]=70;d.masteries[skill.ordinal()]=choice;d.slots[0]=skill.ordinal();d.save(book);p.setItemInHand(InteractionHand.MAIN_HAND,book);clear(p);}
    private static void active(GameTestHelper h,ServerPlayer p){h.onEachTick(()->h.getLevel().getChunkSource().addTicketWithRadius(TicketType.PORTAL,p.chunkPosition(),2));}
    static void menu(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();var d=new MagicData();d.elements=255;d.learned=(1L<<MagicSkill.COUNT)-1;d.save(p.getMainHandItem());var menu=new SpellbookMenu(1,p.getInventory(),0);
        h.assertTrue(!menu.clickMenuButton(p,2000),"Mastery cannot bypass spell level five");d=MagicData.read(p.getMainHandItem());d.uses[0]=70;d.save(p.getMainHandItem());h.assertTrue(menu.clickMenuButton(p,2000),"The first Survival mastery choice costs no ingot");d=MagicData.read(p.getMainHandItem());d.masteries[0]=0;Arrays.fill(d.uses,70);d.save(p.getMainHandItem());p.setGameMode(GameType.CREATIVE);
        for(var skill:MagicSkill.values())for(int choice=1;choice<=2;choice++){h.assertTrue(menu.clickMenuButton(p,2000+skill.ordinal()*2+choice-1),"All 78 choices can be selected on the authoritative menu");h.assertTrue(MagicData.read(p.getMainHandItem()).mastery(skill)==choice,"Choice persists per spell, not per element");}
        p.setGameMode(GameType.SURVIVAL);h.assertTrue(!menu.clickMenuButton(p,2000),"Changing an existing Survival mastery requires an ingot");p.getInventory().setItem(1,new ItemStack(SpellContent.INFUSED_INGOT.get(),2));h.assertTrue(menu.clickMenuButton(p,2000)&&p.getInventory().getItem(1).getCount()==1,"Changing costs exactly one ingot");h.assertTrue(!menu.clickMenuButton(p,2000)&&p.getInventory().getItem(1).getCount()==1,"Selecting the same choice cannot spend twice");
        h.assertTrue(!menu.clickMenuButton(p,2078),"Out-of-range specialization packet is rejected");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(MagicContent.MASTER_BOOK.get()));h.assertTrue(!menu.clickMenuButton(p,2001),"Replacing the book invalidates the original menu");
    }h.succeed();}
    static void migration(GameTestHelper h){var book=new ItemStack(MagicContent.MASTER_BOOK.get());var d=new MagicData();d.elements=255;d.learned=(1L<<MagicSkill.COUNT)-1;Arrays.fill(d.uses,70);d.slots[4]=38;d.selected=4;for(var skill:MagicSkill.values())d.masteries[skill.ordinal()]=skill.ordinal()%2+1;d.save(book);var ops=h.getLevel().registryAccess().createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE);var copy=ItemStack.CODEC.parse(ops,ItemStack.CODEC.encodeStart(ops,book).getOrThrow()).getOrThrow();var loaded=MagicData.read(copy);
        for(var skill:MagicSkill.values())h.assertTrue(loaded.mastery(skill)==skill.ordinal()%2+1,"Every mastery survives a native stack save/load");h.assertTrue(loaded.identity.equals(d.identity)&&loaded.selected==4&&loaded.slots[4]==38,"Masteries retain legacy book identity and five slots");
        net.minecraft.world.item.component.CustomData.update(net.minecraft.core.component.DataComponents.CUSTOM_DATA,copy,t->{t.putInt("magic_mastery_0",99);t.putInt("magic_use_1",40);t.putInt("magic_mastery_2",-1);});loaded=MagicData.read(copy);h.assertTrue(loaded.mastery(MagicSkill.FIRE_BOLT)==0&&loaded.mastery(MagicSkill.FIRE_RING)==0&&loaded.mastery(MagicSkill.FIRE_GUARD)==0,"Bad choices and non-level-five saved masteries are sanitized");
        var old=new ItemStack(SpellContent.FIRE_BOOK.get());h.assertTrue(MagicData.read(old).mastery(MagicSkill.FIRE_BOLT)==0&&MagicData.read(old).knows(0),"Old books acquire no automatic specialization and retain their first spell");h.succeed();}
    private static void visit(GameTestHelper h,MagicSkill s,Set<MagicSkill> path){h.assertTrue(path.add(s),"No prerequisite cycles including cross-links");for(var r:s.requirements()){h.assertTrue(r.skill().element()==s.element()&&r.level()>=1&&r.level()<=4,"Cross-links stay within their element and trainable ranks");visit(h,r.skill(),new HashSet<>(path));}}
    static void graph(GameTestHelper h){int linked=0;for(var s:MagicSkill.values()){visit(h,s,new HashSet<>());if(s.requirements().size()>1)linked++;var d=new MagicData();d.elements=255;for(var r:s.requirements()){d.learned|=1L<<r.skill().ordinal();d.uses[r.skill().ordinal()]=70;}h.assertTrue(d.canLearn(s.ordinal()),"Complete requirements allow unlock");for(var r:s.requirements()){d.uses[r.skill().ordinal()]=0;h.assertTrue(!d.canLearn(s.ordinal()),"Each prerequisite is enforced individually");d.uses[r.skill().ordinal()]=70;}}
        h.assertTrue(linked==5&&MagicSkill.FIRE_GUARD.column()==3&&MagicSkill.STORM_FIELD.column()==3,"Five branch joins and deeper chains replace the flat three-column layout");h.succeed();}
    static void ray(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();var first=enemy(h,5.5,7.5);var second=enemy(h,5.5,10.5);var behind=enemy(h,5.5,14.5);for(int x=4;x<=6;x++)for(int y=2;y<=5;y++)h.setBlock(x,y,12,Blocks.STONE);select(p,MagicSkill.FIRE_BOLT,1);p.setYRot(0);p.setXRot(0);h.assertTrue(MagicCasting.cast(p,0)&&first.getHealth()<100&&second.getHealth()<100&&behind.getHealth()==100,"Ember ray pierces consecutive enemies and stops at walls");h.assertTrue(h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.projectile.hurtingprojectile.SmallFireball.class,p.getBoundingBox().inflate(20)).isEmpty(),"Chosen ray replaces the ordinary fireball");}h.succeed();}
    static void fan(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();var left=enemy(h,2.5,9.5);var right=enemy(h,8.5,9.5);var behind=enemy(h,5.5,3.5);select(p,MagicSkill.FIRE_BOLT,2);p.setYRot(0);p.setXRot(0);h.assertTrue(MagicCasting.cast(p,0)&&left.getHealth()<100&&right.getHealth()<100&&behind.getHealth()==100,"Flame fan covers both sides of the cone but not enemies behind you");}h.succeed();}
    static void marks(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();var target=enemy(h,5.5,8.5);var neighbor=enemy(h,7.5,8.5);select(p,MagicSkill.EMBER_MARK,1);p.lookAt(net.minecraft.commands.arguments.EntityAnchorArgument.Anchor.EYES,target.getEyePosition());h.assertTrue(MagicCasting.cast(p,0),"Ignition mark casts");select(p,MagicSkill.EMBER_MARK,2);MagicExpansion.fireHit(p,target);h.assertTrue(!MagicExpansion.marked(p,target,true)&&target.getHealth()<100,"A mark retains its one-hit mastery after switching books");h.assertTrue(MagicCasting.cast(p,0)&&MagicExpansion.marked(p,neighbor,true),"Ember Kin spreads actual owner-bound marks to nearby targets");}h.succeed();}
    static void veil(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();var target=enemy(h,5.5,8.5);select(p,MagicSkill.WATER_VEIL,1);MagicCasting.cast(p,0);p.hurtServer(h.getLevel(),h.getLevel().damageSources().mobAttack(target),10);h.assertTrue(Math.abs(p.getHealth()-18)<.01,"Deep Water Skin prevents eighty percent once");p.damageCooldownTime=0;p.hurtServer(h.getLevel(),h.getLevel().damageSources().mobAttack(target),4);h.assertTrue(Math.abs(p.getHealth()-14)<.01,"Mastered veil is consumed by one hit");p.setHealth(20);p.damageCooldownTime=0;select(p,MagicSkill.WATER_VEIL,2);MagicCasting.cast(p,0);p.hurtServer(h.getLevel(),h.getLevel().damageSources().mobAttack(target),4);h.assertTrue(target.hasEffect(MobEffects.SLOWNESS)&&target.getEffect(MobEffects.SLOWNESS).getAmplifier()==2,"Binding Spray controls the actual next attacker");}h.succeed();}
    static void reactive(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();var target=enemy(h,5.5,8.5);select(p,MagicSkill.ENDER_WARD,2);MagicCasting.cast(p,0);p.removeAllEffects();p.hurtServer(h.getLevel(),h.getLevel().damageSources().mobAttack(target),8);h.assertTrue(p.getHealth()==16,"Rift Shield halves the next health hit");p.damageCooldownTime=0;p.hurtServer(h.getLevel(),h.getLevel().damageSources().mobAttack(target),4);h.assertTrue(p.getHealth()==12,"Rift Shield is consumed, not refreshed by incoming damage");p.setHealth(20);p.damageCooldownTime=0;select(p,MagicSkill.BLOOD_GUARD,2);MagicCasting.cast(p,0);p.removeAllEffects();p.setAbsorptionAmount(0);p.hurtServer(h.getLevel(),h.getLevel().damageSources().mobAttack(target),4);h.assertTrue(target.hasEffect(KatanaEffects.BLOOD),"Blood reprisal inflicts bleeding on an enemy that actually damages its owner");}h.succeed();}
    static void spring(GameTestHelper h){var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get());var p=f.player();active(h,p);p.setHealth(8);select(p,MagicSkill.HEALING_SPRING,1);MagicCasting.cast(p,0);var at=p.position();p.teleportTo(at.x+3.5,at.y,at.z);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.STICK));h.runAfterDelay(22,()->{try(f){h.assertTrue(p.getHealth()>8,"Wide healing field keeps its four-block radius after switching to a weapon");h.succeed();}});}
    static void inertia(GameTestHelper h){var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get());var p=f.player();active(h,p);var e=enemy(h,10.5,5.5);select(p,MagicSkill.INERTIA_FIELD,1);h.assertTrue(MagicCasting.cast(p,0),"Wide inertia casts");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.STICK));h.runAfterDelay(12,()->{try(f){h.assertTrue(e.hasEffect(MobEffects.SLOWNESS),"Captured wide field controls enemies beyond the default four-block radius");h.succeed();}});}
    static void anchor(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();select(p,MagicSkill.TIME_ANCHOR,2);h.assertTrue(MagicCasting.cast(p,0),"Homecoming anchor places");var origin=p.position();p.teleportTo(origin.x+3,origin.y,origin.z);p.setHealth(8);select(p,MagicSkill.TIME_ANCHOR,1);h.assertTrue(MagicCasting.cast(p,0)&&p.position().equals(origin)&&p.getHealth()==12,"Anchor retains its original healing choice after the book changes");}h.succeed();}
    static void afterimage(GameTestHelper h){var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get());var p=f.player();active(h,p);select(p,MagicSkill.AFTERIMAGE,1);p.setYRot(0);p.setXRot(0);h.assertTrue(MagicCasting.cast(p,0),"Long afterimage casts");h.runAfterDelay(66,()->h.assertTrue(!h.getLevel().getEntitiesOfClass(ArmorStand.class,p.getBoundingBox().inflate(10)).isEmpty(),"Extended afterimage survives the ordinary expiry"));h.runAfterDelay(124,()->{try(f){h.assertTrue(h.getLevel().getEntitiesOfClass(ArmorStand.class,p.getBoundingBox().inflate(10)).isEmpty(),"Extended decoy still expires and leaves no persistent entity");h.succeed();}});}
    static void fold(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();select(p,MagicSkill.DIMENSION_FOLD,2);var start=p.position();var at=h.absoluteVec(new Vec3(5.5,2,11.5));p.lookAt(net.minecraft.commands.arguments.EntityAnchorArgument.Anchor.EYES,at.add(0,-.1,0));h.assertTrue(MagicCasting.cast(p,0),"Guarded passage creates safe paired portals");p.setShiftKeyDown(true);MagicExpansion.tick(h.getLevel());h.assertTrue(p.position().distanceToSqr(start)>9&&p.hasEffect(MobEffects.REGENERATION)&&p.hasEffect(MobEffects.RESISTANCE),"Actual traversal grants both chosen protective effects");var arrived=p.position();MagicExpansion.tick(h.getLevel());h.assertTrue(p.position().equals(arrived),"Mastery retains portal ping-pong protection");p.setShiftKeyDown(false);}h.succeed();}
    static void cooldown(GameTestHelper h){var feedback=new SpellCooldownFeedback();h.assertTrue(!feedback.tick(true,0)&&!feedback.tick(true,0),"Already-ready books and logins stay silent");h.assertTrue(!feedback.tick(true,40)&&!feedback.tick(true,20)&&feedback.tick(true,0)&&!feedback.tick(true,0),"One native cooldown emits exactly one ready cue");feedback.tick(true,10);feedback.tick(false,0);h.assertTrue(!feedback.tick(true,0),"Unequipping prevents delayed ready spam");feedback.tick(true,4);feedback.reset();h.assertTrue(!feedback.tick(true,0),"World/player reset clears previous cooldown tracking");
        try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();select(p,MagicSkill.ENDER_CHEST,1);h.assertTrue(MagicCasting.cast(p,0),"Quick Access opens native Ender Chest");h.assertTrue(at.janic.thedarkdimensions.resonance.AncientRunes.remaining(p.getCooldowns(),p.getCooldowns().getCooldownGroup(p.getMainHandItem()))==24,"Chosen Ender Chest mastery halves actual shared cooldown");p.closeContainer();}h.succeed();}
    static void blood(GameTestHelper h){var e=enemy(h,5.5,7.5);var effect=new MobEffectInstance(KatanaEffects.BLOOD,100,0);h.assertTrue(effect.getParticleOptions().getType()==KatanaEffects.BLOOD_DROP.get(),"Bleeding exposes its own droplet particle instead of the potion swirl");h.assertTrue(KatanaEffects.BLOOD.get().getColor()==0xb51424,"Bleeding tint is red");e.setHealth(1);KatanaEffects.BLOOD.get().applyEffectTick(h.getLevel(),e,0);h.assertTrue(!e.isAlive(),"Red blood presentation retains lethal bleeding damage");h.succeed();}
    static void catalog(GameTestHelper h){for(String lang:List.of("de_de","en_us"))try(var input=MasteryTests.class.getResourceAsStream("/assets/thedarkdimensions/lang/"+lang+".json")){var json=com.google.gson.JsonParser.parseReader(new java.io.InputStreamReader(input,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();for(var s:MagicSkill.values())for(int choice=1;choice<=2;choice++){var key=MagicMastery.key(s,choice);h.assertTrue(json.has(key)&&json.has(key+".desc")&&!json.get(key).getAsString().isBlank(),"Every one of 78 choices has a localized name and explanation");}}catch(Exception e){throw new IllegalStateException(e);}h.succeed();}
    static void sources(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();select(p,MagicSkill.WATER_HEAL,1);var book=p.getMainHandItem().copy();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(KatanaContent.FROSTGLEAM.get()));p.setItemInHand(InteractionHand.OFF_HAND,book);p.setHealth(8);h.assertTrue(MagicCasting.cast(p,1)&&p.getHealth()==20&&MagicData.read(MagicBooks.get(p,1)).mastery(MagicSkill.WATER_HEAL)==1,"Offhand casting uses the offhand book's mastery alongside a katana");
        if(BackEquipment.trinkets()){clear(p);TrinketsMagic.set(p,MagicBooks.get(p,1).copy());p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);p.setHealth(8);h.assertTrue(MagicBooks.active(p)==3&&MagicCasting.cast(p,3)&&p.getHealth()==20&&MagicData.read(TrinketsMagic.get(p)).mastery(MagicSkill.WATER_HEAL)==1,"Equipped Trinkets spellbook retains and casts its own specialization");}
    }h.succeed();}
    static void chain(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();var first=enemy(h,5.5,7.5);var next=enemy(h,8.5,7.5);var third=enemy(h,11.5,7.5);MagicExpansion.chain(p,first,5,0);float normal=100-third.getHealth(),firstDamage=100-first.getHealth();for(var e:List.of(first,next,third)){e.setHealth(100);e.damageCooldownTime=0;}MagicExpansion.chain(p,first,5,2);h.assertTrue(100-third.getHealth()>normal&&Math.abs((100-first.getHealth())-firstDamage)<.001,"Steady Current preserves the first hit and reduces later falloff");}h.succeed();}
}
